def _scope(**overrides) -> ReviewScope:
    base = dict(
        project_root="/proj",
        project_name="proj",
        default_branch="origin/main",
        language="Python",
        build_system="make",
        test_framework="pytest",
    )
    base.update(overrides)
    return ReviewScope(**base)


