class TestLensPrompt:
    def test_agent_id_and_identity_fields(self):
        lens = _BY_SLUG["security"]
        text = prompts.build_lens_prompt(lens, DIM, _scope())
        assert 'agent_id to "security/full-scope"' in text
        assert 'concern to "Security"' in text
        assert 'concern_slug to "security"' in text

    def test_conditional_blocks_absent_when_empty(self):
        text = prompts.build_lens_prompt(_BY_SLUG["implementation"], DIM, _scope())
        assert "PR SCOPE:" not in text
        assert "USER GUIDANCE:" not in text
        assert "LOCAL STANDARDS:" not in text
        assert "shared infrastructure" not in text

    def test_conditional_blocks_present_when_set(self):
        scope = _scope(
            pr_scope_text="## PR Scope: #5\nstuff",
            guidance="focus on auth",
            standards="Use tabs.",
        )
        text = prompts.build_lens_prompt(_BY_SLUG["implementation"], DIM, scope)
        assert "PR SCOPE:\n## PR Scope: #5" in text
        assert "USER GUIDANCE:\nfocus on auth" in text
        assert "LOCAL STANDARDS:\nUse tabs." in text

    def test_shared_infrastructure_block(self):
        dim = {"name": "core", "slug": "core", "scope": {"shared_infrastructure": True}}
        text = prompts.build_lens_prompt(_BY_SLUG["implementation"], dim, _scope())
        assert "shared infrastructure" in text

    def test_categorical_vs_simple_rating_lines(self):
        cat = prompts.build_lens_prompt(_BY_SLUG["implementation"], DIM, _scope())
        assert "_justification" in cat
        assert "five categorical dimensions" in cat
        simple = prompts.build_lens_prompt(
            _BY_SLUG["implementation"], DIM, _scope(), scoring="simple"
        )
        assert "_justification" not in simple
        assert "severity" in simple and "confidence" in simple
        # Shared skeleton stays intact in both.
        for text in (cat, simple):
            assert "HARD EXCLUSIONS" in text
            assert "PROHIBITED ACTIONS" in text
            assert "METHODOLOGY" in text


class TestSelectorPrompt:
    def test_pr_mode_uses_merge_base(self):
        scope = _scope(merge_base="abc123", pr_scope_text="## PR Scope: #5")
        text = prompts.build_selector_prompt(scope, LENSES)
        assert "git diff --name-status abc123..HEAD" in text
        assert "full-repository review" not in text

    def test_full_repo_mode(self):
        text = prompts.build_selector_prompt(_scope(), LENSES)
        assert "git ls-files" in text
        assert "full-repository review" in text

    def test_roster_and_rules(self):
        text = prompts.build_selector_prompt(_scope(), LENSES)
        for lens in LENSES:
            assert f"- {lens.slug}: " in text
        assert "implementation (general correctness) always runs" in text
        assert "max 3" in text


class TestValidatorPrompt:
    BATCH = {
        "batch_number": 1,
        "total_batches": 2,
        "findings": [
            {
                "title": "Bug",
                "content_hash": "deadbeefdeadbeef",
                "concern_slug": "implementation",
                "runtime_scope": "service-internal",
                "runtime_scope_justification": "core lib",
                "failure_mode": "crash-or-outage",
                "failure_mode_justification": "unhandled",
                "evidence_quality": "demonstrated",
                "evidence_quality_justification": "traced",
                "trace_origin": "entry-point",
                "trace_origin_justification": "cli main",
                "effort_to_fix": "small",
                "locations": [{"path": "a.py", "line": "3"}],
                "issue": "It crashes",
                "why_it_matters": "Outage",
                "suggested_fix": "Guard it",
            }
        ],
    }

    def test_attribution_gated_on_base_ref(self):
        with_base = prompts.build_validator_prompt(self.BATCH, "/proj", "abc123")
        without = prompts.build_validator_prompt(self.BATCH, "/proj", "")
        assert "PR ATTRIBUTION CHECK" in with_base
        assert "git diff abc123...HEAD" in with_base
        assert "PR ATTRIBUTION CHECK" not in without
        assert "4. Challenge attribution" in with_base
        assert "4. Challenge attribution" not in without

    def test_content_hash_rule_and_finding_block(self):
        text = prompts.build_validator_prompt(self.BATCH, "/proj", "")
        assert "content_hash EXACTLY" in text
        assert "content_hash: deadbeefdeadbeef" in text
        assert "runtime_scope: service-internal — core lib" in text

    def test_simple_mode_blocks(self):
        batch = {
            "batch_number": 1,
            "total_batches": 1,
            "findings": [
                {
                    "title": "Bug",
                    "content_hash": "deadbeefdeadbeef",
                    "concern_slug": "implementation",
                    "severity": "critical",
                    "confidence": "high",
                    "locations": [{"path": "a.py"}],
                    "issue": "x",
                    "why_it_matters": "y",
                    "suggested_fix": "z",
                }
            ],
        }
        text = prompts.build_validator_prompt(batch, "/proj", "", simple=True)
        assert "severity: critical" in text
        assert "new_severity" in text
        assert "runtime_scope" not in text


class TestSelectorPromptBlocks:
    def test_guidance_and_pr_blocks_toggle(self):
        bare = prompts.build_selector_prompt(_scope(), LENSES)
        assert "USER GUIDANCE" not in bare
        assert "## PR Scope" not in bare
        full = prompts.build_selector_prompt(
            _scope(guidance="focus", pr_scope_text="## PR Scope: #9", merge_base="abc123"),
            LENSES,
        )
        assert "USER GUIDANCE" in full and "focus" in full
        assert "## PR Scope: #9" in full


